// Database Seed Script
// Creates initial Admin account, demo data, and platform settings
// Idempotent - can be run multiple times safely
//
// Phase 5 (fresh-database re-baseline): the demo catalog (domains, skills,
// level rules, demo programs, demo assessment questions) now lives here —
// previously it was embedded, with literal non-CUID identifiers, in the
// historical sprint-2 migration (now archived verbatim; see
// prisma/migrations_archive and the Phase-5 decision record). Seeded IDs are
// generated by Prisma (@default(cuid())) so every row conforms to the API
// CUID validators. Seeding logic lives in prisma/seed-core.ts (injectable
// client, unit-tested offline by src/seed-idempotency.test.ts).

import { PrismaClient, UserRole } from '@prisma/client';
import bcrypt from 'bcryptjs';
import { initializeDefaultSettings } from '../src/shared/utils/settings';
import { createAuditLog, AuditAction } from '../src/shared/utils/audit';
import {
  assertSeedAllowed,
  resolveDemoPassword,
  createUserIfNotExists,
  expectedCatalogCounts,
  seedCatalog,
} from './seed-core';

const prisma = new PrismaClient({
  log: ['error', 'warn'],
});

// Demo credentials (obviously fake for academic/demo use)
const ADMIN_EMAIL = 'admin@internpath.demo';
const ADMIN_PASSWORD = 'Demo-738bfa6b91c241a1a2504cbe-Ax9'; // Will be hashed
const ADMIN_NAME = 'System Administrator (Demo)';

const DEMO_STUDENT_EMAIL = 'student@internpath.demo';
const DEMO_STUDENT_PASSWORD = 'Demo-6a2ff3c391e9feb133fa8208-Ax9';
const DEMO_STUDENT_NAME = 'Demo Student (Test Account)';

const DEMO_MENTOR_EMAIL = 'mentor@internpath.demo';
const DEMO_MENTOR_PASSWORD = 'Demo-2e24c83815dd7275aeb28f7c-Ax9';
const DEMO_MENTOR_NAME = 'Demo Mentor (Test Account)';

async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, 12);
}

// Deployment sprint 2026-11-22: the defaults above are committed to the
// repository, so they are acceptable ONLY for local development. Any hosted
// seeding (NODE_ENV=production, which additionally requires the explicit
// INTERNPATH_ALLOW_DEMO_SEED=true override) must supply fresh passwords via
// DEMO_ADMIN_PASSWORD / DEMO_STUDENT_PASSWORD / DEMO_MENTOR_PASSWORD
// (resolveDemoPassword refuses the committed defaults in production).
const shown = (password: string, fromEnv: boolean) => (fromEnv ? '(from environment)' : password);

async function seed() {
  // Phase 8 (owner-approved): fail-closed production guard — must run before
  // any database access.
  assertSeedAllowed(process.env);
  const { password: adminPassword, fromEnv: adminFromEnv } = resolveDemoPassword(
    process.env, 'DEMO_ADMIN_PASSWORD', ADMIN_PASSWORD);
  const { password: studentPassword, fromEnv: studentFromEnv } = resolveDemoPassword(
    process.env, 'DEMO_STUDENT_PASSWORD', DEMO_STUDENT_PASSWORD);
  const { password: mentorPassword, fromEnv: mentorFromEnv } = resolveDemoPassword(
    process.env, 'DEMO_MENTOR_PASSWORD', DEMO_MENTOR_PASSWORD);

  console.log('🌱 Starting database seed...\n');

  try {
    const SYSTEM_ACTOR_ID: string | undefined = undefined; // system actions log with NULL actor (schema: nullable for system actions)

    // 1. Initialize default platform settings
    console.log('📋 Initializing platform settings...');
    await initializeDefaultSettings(SYSTEM_ACTOR_ID);
    console.log('  ✅ Platform settings initialized\n');

    // 2. Demo accounts (hash here — the seed core is hash-free/testable)
    console.log('👤 Creating demo accounts (admin, student, mentor)...');
    const mockLogger = console; // structured logging passthrough
    await createUserIfNotExists(
      prisma,
      {
        email: ADMIN_EMAIL,
        passwordHash: await hashPassword(adminPassword),
        fullName: ADMIN_NAME,
        role: UserRole.ADMIN,
        mustChangePassword: false, // Admin doesn't need forced password change
      },
      mockLogger
    );
    await createUserIfNotExists(
      prisma,
      {
        email: DEMO_STUDENT_EMAIL,
        passwordHash: await hashPassword(studentPassword),
        fullName: DEMO_STUDENT_NAME,
        role: UserRole.STUDENT,
        mustChangePassword: false,
      },
      mockLogger
    );
    await createUserIfNotExists(
      prisma,
      {
        email: DEMO_MENTOR_EMAIL,
        passwordHash: await hashPassword(mentorPassword),
        fullName: DEMO_MENTOR_NAME,
        role: UserRole.MENTOR,
        mustChangePassword: false,
      },
      mockLogger
    );
    console.log('');

    // 3. Demo catalog (domains, skills, level rules, programs, questions)
    console.log('📦 Seeding demo catalog (domains, skills, level rules, programs, questions)...');
    const catalogCounts = await seedCatalog(prisma);
    console.log(
      `  ✔ Catalog done: ${catalogCounts.created} created, ${catalogCounts.existing} already present\n`
    );

    // 4. Audit log entry for the seed
    await createAuditLog({
      actorId: SYSTEM_ACTOR_ID,
      action: AuditAction.SYSTEM_SEED,
      entityType: 'System',
      entityId: 'seed',
      newValue: {
        adminEmail: ADMIN_EMAIL,
        demoStudentEmail: DEMO_STUDENT_EMAIL,
        demoMentorEmail: DEMO_MENTOR_EMAIL,
        catalog: {
          ...expectedCatalogCounts(),
          created: catalogCounts.created,
          existing: catalogCounts.existing,
        },
        note: 'Academic/demo environment seed (ASM-CAND-022); fictionally-named demo data only',
      },
      reason: 'Database seed for academic/demo environment',
    });

    console.log('\n✅ Seed completed successfully!');
    console.log('\n📋 Demo Credentials (for testing only):');
    console.log('┌─────────────────────────────────────────────────────────────┐');
    console.log('│  ⚠️  ACADEMIC/DEMO ENVIRONMENT - FICTIONAL DATA ONLY       │');
    console.log('├──────────────┬──────────────────────┬───────────────────────┤');
    console.log('│ Role         │ Email                │ Password              │');
    console.log('├──────────────┼──────────────────────┼───────────────────────┤');
    console.log(`│ Admin        │ admin@internpath.demo │ ${shown(adminPassword, adminFromEnv)} │`);
    console.log(`│ Student      │ student@internpath.demo│ ${shown(studentPassword, studentFromEnv)} │`);
    console.log(`│ Mentor       │ mentor@internpath.demo │ ${shown(mentorPassword, mentorFromEnv)} │`);
    console.log('└──────────────┴──────────────────────┴───────────────────────┤');
    console.log('│ Demo catalog: 5 domains, 33 skills, 10 level rules (66 min- │');
    console.log('│ imums), 3 demo programs, 10 questions (server-side keys).   │');
    console.log('└─────────────────────────────────────────────────────────────┘');
    console.log('\n🔒 IMPORTANT: These are development/demo credentials.');
    console.log('   Do NOT use in production. Change immediately if deployed.');
  } catch (error) {
    console.error('\n❌ Seed failed:', error);
    throw error;
  } finally {
    await prisma.$disconnect();
  }
}

// Run seed if executed directly
seed()
  .then(() => process.exit(0))
  .catch(() => process.exit(1));
